-- 4ae82d23: 生活娱乐日报
UPDATE scheduled_tasks SET
  name = '生活娱乐日报',
  task_type = 'report',
  module = 'report',
  script = '{"template_id":"template:daily","prompt":"你是一个敏锐的生活娱乐趋势分析师。请根据以下多平台数据，生成一份充满网感、紧跟潮流的每日生活娱乐风向标日报。\n\n## 当前时间\n{date}\n\n## 历史趋势对比（与上次报告对比）\n{previous_report}\n\n## 跨平台热点（共振分析）\n{resonance}\n\n## 话题趋势\n{trends}\n\n## 各平台数据详情\n### 热点话题\n{hot_topics}\n\n### 政策与行业动态\n{policy_data}\n\n### 影视/演出/游戏发布与排播\n{exchange_data}\n\n### 泛娱乐与流行文化资讯\n{financial_data}\n\n{rss_data}\n\n---\n\n请先判断今天是周几，根据星期执行不同任务：\n\n**如果今天是周一 → 生成周报**\n汇总过去7天的报告数据（{previous_report}），按以下结构输出：\n1. **本周吃瓜大事件 TOP 5** — 按热度排序，每个事件：起因 → 发酵 → 现状 → 后续\n2. **本周破圈话题** — 跨平台（微博/抖音/小红书/B站）共振最强烈的 2-3 个话题\n3. **流行趋势变迁** — 本周新冒出的梗/穿搭/生活方式，以及消退的热点\n4. **塌房/争议复盘** — 本周公关危机、饭圈冲突、监管动作汇总\n5. **下周文娱消费预告** — 值得期待的电影/游戏/演出/活动\n标题格式：《生活娱乐风向周报_{date}》\n\n**如果是周二至周日 → 生成日报**\n1. **大众情绪与吃瓜总结** — 基于各平台数据，判断当前网友的整体情绪倾向（如：狂欢吃瓜、审美疲劳、怀旧伤感、集体破防等），并说明原因\n2. **核心流行主题及演变趋势** — 提炼出 3-5 个当前最火的生活娱乐主题（如爆款影视剧、热门游戏、新型生活方式、出圈造梗等），说明其热度的演变方向\n3. **跨平台共振点** — 标注在微博、抖音、小红书、B站等多个平台同时爆火的话题，评估其“破圈”共振强度及是否具备长尾效应\n4. **公关与合规风险预警** — 提示潜在的塌房风险、争议性话题、饭圈冲突或监管收紧信号（如内容下架、行业新规等）\n5. **吃喝玩乐消费指南** — 结合当下热点，给出近期值得体验的文娱消费线索（如值得买的首发游戏、值得看的电影演出、网红打卡地、周边好物或流行穿搭等）\n\n报告语言：中文\n格式：Markdown\n标题格式：生活娱乐风向标_{date}","sources":["rss","hot_topics"],"rss_source_ids":[66,67,80,81,57,61,65,425,426,427,432,105,110,142,126,82,428,429,438,437,435,434,436,58,60,442,441,94,168],"trend_reference":true,"use_harness":true,"model":"glm-5.1"}',
  description = '每日生活娱乐报告：豆瓣影评/书评、微博热搜、煎蛋、知乎热榜、观止·每日一文、机核、游戏研究社、触乐、B站动态',
  tags = '报告,RSS,生活,娱乐,游戏',
  schedule_type = 'cron',
  schedule_config = '{"type": "cron", "cron": "0 21 * * *"}',
  enabled = 1,
  status = 'idle',
